            <TextInput accessibilityLabel="Publisher" value={editPublisher} onChangeText={setEditPublisher} placeholder="Publisher" placeholderTextColor={p.muted} style={[styles.input,{color:p.ink,borderColor:p.line,backgroundColor:p.raised}]}/>
            <TextInput accessibilityLabel="ISBN" autoCapitalize="characters" autoCorrect={false} value={editISBN} onChangeText={setEditISBN} placeholder="ISBN" placeholderTextColor={p.muted} style={[styles.input,{color:p.ink,borderColor:p.line,backgroundColor:p.raised}]}/>
            <TextInput accessibilityLabel="ASIN" autoCapitalize="characters" autoCorrect={false} value={editASIN} onChangeText={setEditASIN} placeholder="ASIN" placeholderTextColor={p.muted} style={[styles.input,{color:p.ink,borderColor:p.line,backgroundColor:p.raised}]}/>
            <TextInput accessibilityLabel="Language" autoCapitalize="none" value={editLanguage} onChangeText={setEditLanguage} placeholder="Language" placeholderTextColor={p.muted} style={[styles.input,{color:p.ink,borderColor:p.line,backgroundColor:p.raised}]}/>
            <TextInput accessibilityLabel="Description" multiline value={editDescription} onChangeText={setEditDescription} placeholder="Description" placeholderTextColor={p.muted} style={[styles.input,{color:p.ink,borderColor:p.line,backgroundColor:p.raised,minHeight:96,textAlignVertical:'top'}]}/>
          </View>:null}
          {localEdit?<View style={{gap:10}}>
            <View style={styles.metadataCoverEditor}>
              <View style={styles.metadataCoverPreview}><Artwork session={session} p={p} title={editTitle||editing.title} format={editing.format} coverShape={editing.coverShape} coverUri={editCoverUri||editing.coverUri}/></View>
              <View style={{flex:1,gap:6}}>
                <Text style={[styles.bookTitle,{color:p.ink}]}>Cover artwork</Text>
                <Text style={[styles.meta,{color:p.muted}]}>{editPickedCover?'Device image selected. Save details to make it the protected manual cover.':localMetadataOverrides[editing.uri!]?.coverUri?'Manual cover · protected from rescans':'Archivist uses the best local artwork it finds unless you choose a cover manually.'}</Text>
                <Button label={coverPicking?'Opening photos…':'Choose image from device'} tone="quiet" disabled={coverPicking||busy} onPress={()=>void chooseCoverFromDevice()}/>
              </View>
            </View>
            {localCoverCandidates.length?<View style={{gap:6}}>
              <Text style={[styles.meta,{color:p.muted}]}>Other local artwork</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:10,paddingVertical:2}}>
                {localCoverCandidates.map((uri,index)=>{
                  const selected=!editPickedCover&&editCoverUri===uri;
                  return <Pressable
                    key={uri}
                    accessibilityRole="button"
                    accessibilityLabel={'Use local cover '+(index+1)}
                    accessibilityState={{selected}}
                    onPress={()=>{setEditPickedCover(null);setEditCoverUri(uri)}}
                    style={({pressed})=>[{width:64,opacity:pressed?.72:1,borderWidth:selected?2:0,borderColor:p.sage,borderRadius:9,overflow:'hidden'}]}>
                    <Artwork session={session} p={p} title={editTitle||editing.title} format={editing.format} coverShape={editing.coverShape} coverUri={uri}/>
                  </Pressable>;
                })}
              </ScrollView>
            </View>:null}
          </View>:null}
          {!localEdit?<Text style={[styles.meta,{color:p.muted}]}>Server cover art is refreshed from the source file or companion artwork during a server scan. Text metadata saved here is marked manual and protected from later scans.</Text>:null}
          <Button label="Save details" disabled={busy||coverPicking||(!editTitle.trim()&&!editAuthor.trim())} onPress={()=>void save()}/>
          {editing.scannerWorkId?<View style={styles.settingsSubgroup}>
            <Button label={editorDirty?'Save details first':assistState?.state==='pending'?'Searching…':'Archivist Assist'} tone="quiet" disabled={busy||coverPicking||editorDirty||assistState?.state==='pending'} onPress={()=>void runAssist()}/>
            {assistState?<Text accessibilityLiveRegion="polite" style={[styles.meta,{color:assistState.state==='error'?p.gold:p.muted}]}>{assistFeedback(assistState)}</Text>:null}
            {assistState?.result?.candidates.map(row=><Button key={row.candidate.provider+'|'+row.candidate.id} label={(row.candidate.fields.title||'Untitled')+' · '+(row.candidate.fields.author||'Unknown author')} tone="quiet" disabled={busy||editorDirty} onPress={()=>{
              const id=row.candidate.provider+'|'+row.candidate.id;
              if(row.conflicts.length)Alert.alert('Replace conflicting details?',row.conflicts.includes('anthology')?'This result is an anthology and cannot identify the individual story.':'This match conflicts with '+row.conflicts.join(', ')+'. Your saved details change only if you approve.',[{text:'Keep my details',style:'cancel'},...(row.conflicts.includes('anthology')?[]:[{text:'Accept replacement',onPress:()=>void acceptAssist(id,true)}])]);
              else void acceptAssist(id);
            }}/>) }
            {Object.entries(assistState?.result?.nextPages||{}).filter(([,page])=>page!==null).map(([provider,page])=><Button key={provider} label={'More matches · '+provider} tone="quiet" disabled={busy||editorDirty} onPress={()=>void moreAssist(provider,page!)}/>)}
            <Button label="Confirm saved identity" tone="quiet" disabled={busy||editorDirty||!editTitle.trim()||!editAuthor.trim()} onPress={()=>void confirmDetails()}/>
            {normalizeGenre(editGenre?[{value:editGenre,source:'manual'}]:[]).state!=='confirmed'?<Text style={[styles.meta,{color:p.gold}]}>A clear genre is needed before this work is ready for Atlas.</Text>:null}
          </View>:null}
          {localEdit&&!editing.scannerWorkId?<Button label="Use scanned metadata & cover" tone="quiet" disabled={busy} onPress={()=>void restoreScanned()}/>:null}
          <Button label="Cancel" tone="quiet" disabled={busy||coverPicking} onPress={requestEditorClose}/>
        </Pressable>
      </ScrollView></Pressable>
    </KeyboardAvoidingView>
  </Modal>;
}

changes.new:
  function MetadataEditorPanel(){
    if(!editing)return null;
    const localEdit=editing.source!=='server'&&!!editing.uri;
    const targets=editingUris.length?editingUris:(editing.uri?[editing.uri]:[]);
    const draftVersion=metadataDraftRef.current;
    const assistCompleted=async(id:string,state:AssistState)=>{
      if(editingScannerId.current===id)setAssistState(state);
      if(state.state!=='accepted')return;
      const runtime=await freshRuntime(),rows=await runtime.refresh(id);await applyScannerRows(rows);
      if(editingScannerId.current!==id||metadataDraftRef.current!==draftVersion)return;
      const latest=await runtime.metadata.get(id);if(!latest||metadataDraftRef.current!==draftVersion)return;
      const f=latest.fields,cover=rows[0]?.coverUri||f.coverUri||'';
      setEditing(current=>current?.scannerWorkId===id?{...current,...f,seriesNumber:f.seriesNumber?Number(f.seriesNumber):undefined,publishedYear:f.publishedYear?Number(f.publishedYear):undefined,coverUri:cover}:current);
      setEditTitle(f.title||'');setEditAuthor(f.author||'');setEditSeries(f.series||'');setEditSeriesNumber(f.seriesNumber||'');setEditGenre(f.genre||'');setEditYear(f.publishedYear||'');setEditNarrator(f.narrator||'');setEditPublisher(f.publisher||'');setEditISBN(f.isbn||'');setEditASIN(f.asin||'');setEditLanguage(f.language||'');setEditDescription(f.description||'');setEditCoverUri(cover);
    };
    const save=async()=>{
      const title=editTitle.trim(),author=editAuthor.trim(),seriesName=editSeries.trim(),genre=editGenre.trim();
      const seriesNumberText=editSeriesNumber.trim();
      const seriesNumber=seriesNumberText!==''&&Number.isFinite(Number(seriesNumberText))?Number(seriesNumberText):undefined;
      const yearText=editYear.trim();
      const publishedYear=/^\d{4}$/.test(yearText)?Number(yearText):undefined;
      const narrator=editNarrator.trim(),publisher=editPublisher.trim(),isbn=editISBN.trim(),asin=editASIN.trim(),language=editLanguage.trim(),description=editDescription.trim();
      let coverUri=editCoverUri.trim();
      if(!title&&!author)return;
      if(localEdit&&editPickedCover){
        try{coverUri=await persistPickedCover(editPickedCover.uri,editPickedCover.fileName,editPickedCover.fileSize);}
        catch(e){setError('Could not save the selected cover: '+(e as Error).message);return;}
      }
      setBusy(true);setError('');
      if(editing.source==='server'){
        if(!session || (editing.originServer&&editing.originServer!==session.server) || !owner){setBusy(false);setError('Reconnect to the correct server as an admin to edit this file.');return;}
        request(session,'/api/assets/'+editing.id+'/metadata','PATCH',{title,author,series:seriesName,seriesNumber:seriesNumber??0,genre,publishedYear:publishedYear??0,narrator,publisher,isbn,asin,language,description})
          .then(()=>{setServerBooks(old=>old.map(b=>b.id===editing.id?{...b,title,author,series:seriesName,seriesNumber,genre,publishedYear,narrator,publisher,isbn,asin,language,description,needsReview:false,reviewReason:'',metadataSource:'manual',identificationConfidence:'high'}:b));setEditing(null);setEditingUris([]);setEditPickedCover(null);})
          .catch(e=>setError(e.message)).finally(()=>setBusy(false));
      }else if(editing.scannerWorkId){
        const id=editing.scannerWorkId;
        try{
          const runtime=await freshRuntime(),current=await runtime.metadata.get(id);if(!current)throw new Error('Work is unavailable. Prepare the library again.');
          const draft=toFields({title,author,series:seriesName,seriesNumber,genre,publishedYear,narrator,publisher,isbn,asin,language,description,coverUri:coverUri||undefined});
          const patch=Object.fromEntries(Object.entries(draft).filter(([key,value])=>current.fields[key as keyof typeof current.fields]!==value));
          const result=await runtime.save(id,patch,assistPolicy());
          await applyScannerRows(await runtime.refresh(id));
          setEditing({...editing,title,author,series:seriesName,seriesNumber,genre,publishedYear,narrator,publisher,isbn,asin,language,description,coverUri:coverUri||editing.coverUri});setEditPickedCover(null);
          setAssistState({revision:result.work.revision,state:'pending',updated:Date.now()});
          void result.completion.then(state=>assistCompleted(id,state)).catch(()=>{if(editingScannerId.current===id)setAssistState({revision:result.work.revision,state:'error',updated:Date.now()});});
        }catch(e){setError((e as Error).message);}finally{setBusy(false);}
      }else if(editing.uri){
        const override:LocalMetadataOverride={title,author,series:seriesName,seriesNumber,genre,publishedYear,narrator,publisher,isbn,asin,language,description,coverUri:coverUri||undefined};
        const next={...localMetadataOverrides};
        for(const uri of targets)next[uri]=override;
        setLocalMetadataOverrides(next);
        setPersistedJSON(localMetadataOverridesKey,next)
          .then(()=>{
            setLocalBooks(old=>{
              const wanted=new Set(targets);
              const updated=old.map(b=>(b.uri?wanted.has(b.uri):false)?{...b,title,author,series:seriesName,seriesNumber,genre,publishedYear,narrator,publisher,isbn,asin,language,description,coverUri:coverUri||b.coverUri,needsReview:false,reviewReason:'',metadataSource:'manual' as const,identificationConfidence:'high' as const,metadataConflicts:[]}:b);
              void replaceLocalStageBooks(updated as LocalBook[]);
              return updated;
            });
            setEditing(null);setEditingUris([]);setEditPickedCover(null);
          })
          .catch(e=>setError(e.message)).finally(()=>setBusy(false));
      }else setBusy(false);
    };
    const runAssist=async()=>{
      if(!editing.scannerWorkId||busy)return;setBusy(true);setError('');const id=editing.scannerWorkId;
      try{const runtime=await freshRuntime(),result=await runtime.assist.search(id,{...assistPolicy(true),retry:true});setAssistState({revision:result.work.revision,state:'pending',updated:Date.now()});void result.completion.then(state=>assistCompleted(id,state)).catch(()=>{if(editingScannerId.current===id)setAssistState({revision:result.work.revision,state:'error',updated:Date.now()});});}
      catch(e){setError((e as Error).message);}finally{setBusy(false);}
    };
    const acceptAssist=async(candidateId:string,confirm=false)=>{
      if(!editing.scannerWorkId||!assistState||busy)return;setBusy(true);setError('');const id=editing.scannerWorkId;
      try{const runtime=await freshRuntime(),work=await runtime.assist.accept(id,candidateId,assistState.revision,confirm);await applyScannerRows(await runtime.refresh(id));setEditing({...editing,title:work.fields.title||'',author:work.fields.author||'',series:work.fields.series||'',seriesNumber:work.fields.seriesNumber?Number(work.fields.seriesNumber):undefined,genre:work.fields.genre||'',coverUri:work.fields.coverUri});setEditTitle(work.fields.title||'');setEditAuthor(work.fields.author||'');setEditSeries(work.fields.series||'');setEditSeriesNumber(work.fields.seriesNumber||'');setEditGenre(work.fields.genre||'');setEditCoverUri(work.fields.coverUri||'');setAssistState(await runtime.assist.get(id));}
      catch(e){setError((e as Error).message);}finally{setBusy(false);}
    };
    const confirmDetails=async()=>{
      if(!editing.scannerWorkId||busy)return;setBusy(true);setError('');
      try{const runtime=await freshRuntime();await runtime.confirm(editing.scannerWorkId);await applyScannerRows(await runtime.refresh(editing.scannerWorkId));setAssistState(null);}
      catch(e){setError((e as Error).message);}finally{setBusy(false);}
    };
    const moreAssist=async(provider:string,page:number)=>{
      if(!editing.scannerWorkId||!assistState||busy)return;setBusy(true);setError('');
      try{const runtime=await freshRuntime();setAssistState(await runtime.assist.more(editing.scannerWorkId,provider,page,assistState.revision,assistPolicy(true)));}
      catch(e){setError((e as Error).message);}finally{setBusy(false);}
    };
    const chooseCoverFromDevice=async()=>{
      if(!localEdit||coverPicking)return;
      setCoverPicking(true);setError('');
      try{
        const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:false,quality:1,selectionLimit:1});
        const asset=pickedCoverAsset(result);
        if(!asset)return;
        const inspection=await inspectPickedCover(asset.uri,asset.fileSize,{getInfoAsync});
